-- Phase 2. Local artifact only: BACKUP + restore test required before deployment.
-- Source generated by `supabase migration new challenge_game`, relocated to this
-- repository's established sequential migration directory. Run after 0008.
BEGIN;
CREATE TABLE IF NOT EXISTS public.challenge_profiles (
 user_id bigint PRIMARY KEY, display_name text NOT NULL DEFAULT 'طالب',
 branch_id uuid REFERENCES public.challenge_branches(id),
 xp bigint NOT NULL DEFAULT 0 CHECK(xp>=0), trophies integer NOT NULL DEFAULT 0 CHECK(trophies>=0),
 challenges integer NOT NULL DEFAULT 0, wins integer NOT NULL DEFAULT 0, losses integer NOT NULL DEFAULT 0,
 correct integer NOT NULL DEFAULT 0, questions integer NOT NULL DEFAULT 0,
 response_ms bigint NOT NULL DEFAULT 0, responses integer NOT NULL DEFAULT 0,
 defense_wins integer NOT NULL DEFAULT 0, defense_losses integer NOT NULL DEFAULT 0,
 win_streak integer NOT NULL DEFAULT 0,
 notifications_enabled boolean NOT NULL DEFAULT true,
 last_seen timestamptz NOT NULL DEFAULT now(), last_notification_at timestamptz, last_completion_notification_at timestamptz,
 created_at timestamptz NOT NULL DEFAULT now()
);
-- A profile is also the land: no redundant one-to-one lands table.
CREATE INDEX IF NOT EXISTS challenge_profiles_matchmaking ON public.challenge_profiles(branch_id,trophies,user_id);
CREATE TABLE IF NOT EXISTS public.challenge_towers (
 user_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 subject_id uuid NOT NULL REFERENCES public.challenge_subjects(id),
 xp bigint NOT NULL DEFAULT 0, correct integer NOT NULL DEFAULT 0, questions integer NOT NULL DEFAULT 0,
 PRIMARY KEY(user_id,subject_id)
);
CREATE TABLE IF NOT EXISTS public.challenge_unit_stats (
 user_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 unit_id uuid NOT NULL REFERENCES public.challenge_units(id),
 challenges integer NOT NULL DEFAULT 0, wins integer NOT NULL DEFAULT 0,
 correct integer NOT NULL DEFAULT 0, questions integer NOT NULL DEFAULT 0,
 response_ms bigint NOT NULL DEFAULT 0, responses integer NOT NULL DEFAULT 0,
 PRIMARY KEY(user_id,unit_id)
);
CREATE TABLE IF NOT EXISTS public.challenge_matches (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
 kind text NOT NULL DEFAULT 'async_attack' CHECK(kind IN('async_attack','live','friend_link')),
 status text NOT NULL DEFAULT 'created' CHECK(status IN('created','in_progress','completed','expired','abandoned')),
 attacker_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 defender_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 unit_id uuid NOT NULL REFERENCES public.challenge_units(id),
 subject_id uuid NOT NULL REFERENCES public.challenge_subjects(id),
 test_id uuid NOT NULL REFERENCES public.challenge_tests(id), content_hash text NOT NULL,
 request_key text NOT NULL,
 -- Private snapshot: never expose this field through a player-facing query.
 snapshot jsonb NOT NULL, rules jsonb NOT NULL, labels jsonb NOT NULL,
 question_index integer NOT NULL DEFAULT 0,
 question_opened_at timestamptz, question_deadline timestamptz,
 server_deadline timestamptz NOT NULL,
 created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, finished_at timestamptz,
 reward_eligible boolean NOT NULL DEFAULT false, result jsonb,
 telegram_message_id bigint,
 CHECK(attacker_id<>defender_id), UNIQUE(attacker_id,request_key)
);
CREATE UNIQUE INDEX IF NOT EXISTS challenge_one_active_attack ON public.challenge_matches(attacker_id)
 WHERE status IN('created','in_progress');
CREATE INDEX IF NOT EXISTS challenge_attack_history ON public.challenge_matches(attacker_id,created_at DESC);
CREATE INDEX IF NOT EXISTS challenge_defense_history ON public.challenge_matches(defender_id,created_at DESC);
CREATE INDEX IF NOT EXISTS challenge_target_cooldown ON public.challenge_matches(attacker_id,defender_id,created_at DESC);
CREATE INDEX IF NOT EXISTS challenge_content_history ON public.challenge_matches(attacker_id,content_hash,created_at DESC);
CREATE INDEX IF NOT EXISTS challenge_due_questions ON public.challenge_matches(question_deadline)
 WHERE status='in_progress';
CREATE TABLE IF NOT EXISTS public.challenge_match_players (
 match_id uuid NOT NULL REFERENCES public.challenge_matches(id),
 user_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 role text NOT NULL CHECK(role IN('attacker','defender','player')),
 score integer NOT NULL DEFAULT 0, xp_delta integer NOT NULL DEFAULT 0,
 trophies_delta integer NOT NULL DEFAULT 0, PRIMARY KEY(match_id,user_id)
);
CREATE TABLE IF NOT EXISTS public.challenge_match_answers (
 match_id uuid NOT NULL REFERENCES public.challenge_matches(id),
 user_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 question_index integer NOT NULL,
 question_id uuid NOT NULL REFERENCES public.challenge_questions(id),
 option_id integer, is_correct boolean NOT NULL, score integer NOT NULL,
 elapsed_ms integer NOT NULL, timed_out boolean NOT NULL,
 answered_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 update_key text,
 PRIMARY KEY(match_id,user_id,question_index), UNIQUE(user_id,update_key)
);
CREATE TABLE IF NOT EXISTS public.challenge_events (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 match_id uuid NOT NULL REFERENCES public.challenge_matches(id),
 event_type text NOT NULL, question_index integer,
 created_at timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE INDEX IF NOT EXISTS challenge_events_stream ON public.challenge_events(match_id,id);
CREATE TABLE IF NOT EXISTS public.challenge_notifications (
 id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
 match_id uuid NOT NULL REFERENCES public.challenge_matches(id),
 user_id bigint NOT NULL REFERENCES public.challenge_profiles(user_id),
 kind text NOT NULL CHECK(kind IN('attack_started','attack_completed')),
 created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 claimed_at timestamptz, UNIQUE(match_id,user_id,kind)
);
CREATE INDEX IF NOT EXISTS challenge_notifications_pending ON public.challenge_notifications(id) WHERE claimed_at IS NULL;

CREATE OR REPLACE FUNCTION public.challenge_question_score(p_correct boolean,p_elapsed numeric,p_rules jsonb)
RETURNS integer LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=public AS $$
 SELECT CASE WHEN NOT p_correct OR p_elapsed<0 OR p_elapsed >= (p_rules->>'question_seconds')::numeric THEN 0
 ELSE (p_rules->>'accuracy_points')::integer + floor((p_rules->>'speed_bonus')::numeric *
 (1-p_elapsed/(p_rules->>'question_seconds')::numeric))::integer END
$$;

CREATE OR REPLACE FUNCTION public.challenge_touch_profile(p_user bigint,p_name text,p_branch uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE v challenge_profiles;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM feature_flags WHERE key='challenge_system_enabled' AND enabled) THEN
 RAISE EXCEPTION 'game_disabled'; END IF;
 IF p_branch IS NOT NULL AND NOT EXISTS(SELECT 1 FROM challenge_playable_units WHERE branch_id=p_branch) THEN
 RAISE EXCEPTION 'no_content'; END IF;
 INSERT INTO challenge_profiles(user_id,display_name,branch_id)
 VALUES(p_user,left(coalesce(nullif(btrim(p_name),''),'طالب'),80),p_branch)
 ON CONFLICT(user_id) DO UPDATE SET display_name=excluded.display_name,last_seen=clock_timestamp(),
 branch_id=coalesce(excluded.branch_id,challenge_profiles.branch_id) RETURNING * INTO v;
 RETURN to_jsonb(v);
END $$;

-- Reads reveal only the currently open question and finalized public result.
CREATE OR REPLACE FUNCTION public.challenge_attack_state(p_match uuid,p_user bigint)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE m challenge_matches; q jsonb;
BEGIN
 SELECT * INTO m FROM challenge_matches WHERE id=p_match AND attacker_id=p_user;
 IF NOT FOUND THEN RAISE EXCEPTION 'not_your_attack'; END IF;
 IF m.status='in_progress' THEN q:=m.snapshot->m.question_index; END IF;
 RETURN jsonb_build_object('id',m.id,'attacker_id',m.attacker_id,'status',m.status,
 'index',m.question_index,'total',jsonb_array_length(m.snapshot),'labels',m.labels,
 'question',CASE WHEN q IS NULL THEN NULL ELSE jsonb_build_object('text',q->>'text','options',q->'options',
 'image_url',q->>'image_url') END,'deadline',m.question_deadline,'server_now',clock_timestamp(),
 'result',m.result,'message_id',m.telegram_message_id);
END $$;

CREATE OR REPLACE FUNCTION public.challenge_start_attack(
 p_user bigint,p_target bigint,p_unit uuid,p_test uuid,p_request text,p_rules jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE a challenge_profiles; d challenge_profiles; t challenge_tests; u challenge_units;
 s challenge_subjects; b challenge_branches; mid uuid; qs jsonb; stamp timestamptz;
 eligible boolean; labels jsonb; n integer;
BEGIN
 IF p_user=p_target THEN RAISE EXCEPTION 'self_attack'; END IF;
 IF p_request IS NULL OR length(p_request)>160 THEN RAISE EXCEPTION 'invalid_request'; END IF;
 -- Lock all participants in a fixed order; same ordering is used in settlement.
 PERFORM user_id FROM challenge_profiles WHERE user_id IN(p_user,p_target) ORDER BY user_id FOR UPDATE;
 SELECT * INTO a FROM challenge_profiles WHERE user_id=p_user;
 SELECT * INTO d FROM challenge_profiles WHERE user_id=p_target;
 IF a.user_id IS NULL OR d.user_id IS NULL THEN RAISE EXCEPTION 'profile_missing'; END IF;
 SELECT id INTO mid FROM challenge_matches WHERE attacker_id=p_user AND request_key=p_request;
 IF mid IS NOT NULL THEN RETURN challenge_attack_state(mid,p_user); END IF;
 IF NOT EXISTS(SELECT 1 FROM feature_flags WHERE key='challenge_system_enabled' AND enabled)
 OR NOT EXISTS(SELECT 1 FROM feature_flags WHERE key='async_attacks_enabled' AND enabled) THEN
 RAISE EXCEPTION 'game_disabled'; END IF;
 IF EXISTS(SELECT 1 FROM challenge_matches WHERE attacker_id=p_user AND status IN('created','in_progress')) THEN
 RAISE EXCEPTION 'active_attack'; END IF;
 stamp:=clock_timestamp();
 IF EXISTS(SELECT 1 FROM challenge_matches WHERE attacker_id=p_user AND defender_id=p_target
 AND created_at > stamp-make_interval(secs=>(p_rules->>'target_cooldown_seconds')::integer)) THEN
 RAISE EXCEPTION 'target_cooldown'; END IF;
 SELECT count(*) INTO n FROM challenge_matches WHERE attacker_id=p_user AND created_at>=date_trunc('day',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
 IF n >= (p_rules->>'daily_attack_limit')::integer THEN RAISE EXCEPTION 'daily_limit'; END IF;
 -- Locks prevent disable/archive from racing snapshot creation (or vice versa).
 SELECT * INTO t FROM challenge_tests WHERE id=p_test AND unit_id=p_unit AND status='active' FOR SHARE;
 SELECT * INTO u FROM challenge_units WHERE id=p_unit AND status='active' FOR SHARE;
 SELECT * INTO s FROM challenge_subjects WHERE id=u.subject_id AND status='active' FOR SHARE;
 SELECT * INTO b FROM challenge_branches WHERE id=s.branch_id AND status='active' FOR SHARE;
 IF t.id IS NULL OR u.id IS NULL OR s.id IS NULL OR b.id IS NULL THEN RAISE EXCEPTION 'no_content'; END IF;
 IF a.branch_id IS DISTINCT FROM s.branch_id OR d.branch_id IS DISTINCT FROM s.branch_id THEN
 RAISE EXCEPTION 'branch_mismatch'; END IF;
 -- Question pool is bounded to one curated test (maximum 200). No random sort of player tables.
 SELECT jsonb_agg(x.q ORDER BY x.question_order) INTO qs FROM (
 SELECT question_order,jsonb_build_object('id',id,'text',question_text,'options',options,
 'correct_option_id',correct_option_id,'image_url',metadata->>'image_url') q
 FROM challenge_questions WHERE test_id=p_test ORDER BY md5(id::text||p_request)
 LIMIT (p_rules->>'questions_per_attack')::integer) x;
 IF qs IS NULL OR jsonb_array_length(qs)=0 THEN RAISE EXCEPTION 'no_content'; END IF;
 eligible:=NOT EXISTS(SELECT 1 FROM challenge_matches WHERE attacker_id=p_user AND content_hash=t.content_hash
 AND created_at>stamp-make_interval(secs=>(p_rules->>'repeat_content_seconds')::integer));
 labels:=jsonb_build_object('attacker',a.display_name,'defender',d.display_name,'subject',s.name,'unit',u.name,'test',t.title);
 INSERT INTO challenge_matches(attacker_id,defender_id,unit_id,subject_id,test_id,content_hash,request_key,
 snapshot,rules,labels,server_deadline,reward_eligible,created_at)
 VALUES(p_user,p_target,p_unit,s.id,p_test,t.content_hash,p_request,qs,p_rules,labels,
 stamp+make_interval(secs=>(p_rules->>'attack_seconds')::integer),eligible,stamp) RETURNING id INTO mid;
 UPDATE challenge_matches SET status='in_progress',started_at=stamp,question_opened_at=stamp,
 question_deadline=stamp+make_interval(secs=>(p_rules->>'question_seconds')::integer) WHERE id=mid;
 INSERT INTO challenge_match_players(match_id,user_id,role) VALUES(mid,p_user,'attacker'),(mid,p_target,'defender');
 INSERT INTO challenge_events(match_id,event_type,question_index) VALUES(mid,'attack_started',0);
 IF d.notifications_enabled AND d.last_seen>stamp-make_interval(secs=>(p_rules->>'online_seconds')::integer)
 AND (d.last_notification_at IS NULL OR d.last_notification_at<stamp-make_interval(secs=>(p_rules->>'notification_cooldown_seconds')::integer)) THEN
 INSERT INTO challenge_notifications(match_id,user_id,kind) VALUES(mid,p_target,'attack_started');
 UPDATE challenge_profiles SET last_notification_at=stamp WHERE user_id=p_target;
 END IF;
 RETURN challenge_attack_state(mid,p_user);
END $$;

-- Internal helper, called only while participant + match locks are held by advance_attack.
CREATE OR REPLACE FUNCTION public.challenge_finish_attack(p_match uuid,p_status text)
RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE m challenge_matches; n integer; c integer; pts integer; ms bigint; resp integer;
 stars integer:=0; won boolean; xp_award integer:=0; trophy_award integer:=0;
 used_xp integer; used_trophies integer; stamp timestamptz:=clock_timestamp();
BEGIN
 SELECT * INTO m FROM challenge_matches WHERE id=p_match FOR UPDATE;
 IF m.status<>'in_progress' THEN RETURN; END IF;
 n:=jsonb_array_length(m.snapshot);
 IF p_status NOT IN('completed','expired','abandoned') THEN RAISE EXCEPTION 'bad_transition'; END IF;
 IF p_status='completed' AND m.question_index<n THEN RAISE EXCEPTION 'unfinished_attack'; END IF;
 SELECT count(*) FILTER(WHERE is_correct),coalesce(sum(score),0),
 coalesce(sum(elapsed_ms) FILTER(WHERE NOT timed_out),0),count(*) FILTER(WHERE NOT timed_out)
 INTO c,pts,ms,resp FROM challenge_match_answers WHERE match_id=m.id AND user_id=m.attacker_id;
 IF p_status='completed' THEN
 SELECT count(*) INTO stars FROM jsonb_array_elements_text(m.rules->'star_thresholds') v
 WHERE c::numeric/n>=v::numeric;
 END IF;
 won:=stars>0;
 IF won AND m.reward_eligible THEN
 SELECT coalesce(sum((result->>'xp')::integer),0),coalesce(sum((result->>'trophies')::integer),0)
 INTO used_xp,used_trophies FROM challenge_matches WHERE attacker_id=m.attacker_id
 AND finished_at>=date_trunc('day',stamp AT TIME ZONE 'UTC') AT TIME ZONE 'UTC';
 xp_award:=least(c*(m.rules->>'xp_per_correct')::integer,
 greatest(0,(m.rules->>'daily_xp_limit')::integer-used_xp));
 trophy_award:=least(floor(stars*(m.rules->>'trophies_per_star')::numeric * n /
 (m.rules->>'questions_per_attack')::integer)::integer,
 greatest(0,(m.rules->>'daily_trophy_limit')::integer-used_trophies));
 ELSIF NOT won THEN
 SELECT -least(trophies,(m.rules->>'loss_trophies')::integer) INTO trophy_award
 FROM challenge_profiles WHERE user_id=m.attacker_id;
 END IF;
 -- Defender earns no farming rewards and loses no resources while offline.
 UPDATE challenge_profiles SET xp=xp+xp_award,trophies=greatest(0,trophies+trophy_award),
 challenges=challenges+1,wins=wins+won::integer,losses=losses+(NOT won)::integer,
 correct=correct+c,questions=questions+n,response_ms=response_ms+ms,responses=responses+resp,
 win_streak=CASE WHEN won THEN win_streak+1 ELSE 0 END WHERE user_id=m.attacker_id;
 UPDATE challenge_profiles SET defense_losses=defense_losses+won::integer,
 defense_wins=defense_wins+(NOT won)::integer WHERE user_id=m.defender_id;
 INSERT INTO challenge_towers(user_id,subject_id,xp,correct,questions) VALUES(m.attacker_id,m.subject_id,xp_award,c,n)
 ON CONFLICT(user_id,subject_id) DO UPDATE SET xp=challenge_towers.xp+excluded.xp,
 correct=challenge_towers.correct+excluded.correct,questions=challenge_towers.questions+excluded.questions;
 INSERT INTO challenge_unit_stats(user_id,unit_id,challenges,wins,correct,questions,response_ms,responses)
 VALUES(m.attacker_id,m.unit_id,1,won::integer,c,n,ms,resp)
 ON CONFLICT(user_id,unit_id) DO UPDATE SET challenges=challenge_unit_stats.challenges+1,
 wins=challenge_unit_stats.wins+excluded.wins,correct=challenge_unit_stats.correct+excluded.correct,
 questions=challenge_unit_stats.questions+excluded.questions,response_ms=challenge_unit_stats.response_ms+excluded.response_ms,
 responses=challenge_unit_stats.responses+excluded.responses;
 UPDATE challenge_match_players SET score=pts,xp_delta=xp_award,trophies_delta=trophy_award
 WHERE match_id=m.id AND user_id=m.attacker_id;
 UPDATE challenge_matches SET status=p_status,finished_at=stamp,result=jsonb_build_object(
 'correct',c,'total',n,'accuracy',round(c::numeric/n,4),'score',pts,'stars',stars,'won',won,
 'xp',xp_award,'trophies',trophy_award,'reward_eligible',m.reward_eligible,
 'average_response_ms',CASE WHEN resp>0 THEN ms/resp ELSE 0 END,
 'duration_seconds',extract(epoch FROM stamp-m.started_at)::integer) WHERE id=m.id;
 INSERT INTO challenge_events(match_id,event_type) VALUES(m.id,'attack_completed');
 INSERT INTO challenge_notifications(match_id,user_id,kind) VALUES(m.id,m.defender_id,'attack_completed') ON CONFLICT DO NOTHING;
END $$;

CREATE OR REPLACE FUNCTION public.challenge_advance_attack(p_match uuid,p_user bigint,
 p_action text DEFAULT 'resume',p_index integer DEFAULT NULL,p_option integer DEFAULT NULL,p_update text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE m challenge_matches; target bigint; stamp timestamptz; q jsonb; expired boolean; correct boolean;
 ms integer; pts integer; n integer;
BEGIN
 SELECT defender_id INTO target FROM challenge_matches WHERE id=p_match AND attacker_id=p_user;
 IF NOT FOUND THEN RAISE EXCEPTION 'not_your_attack'; END IF;
 PERFORM user_id FROM challenge_profiles WHERE user_id IN(p_user,target) ORDER BY user_id FOR UPDATE;
 SELECT * INTO m FROM challenge_matches WHERE id=p_match FOR UPDATE;
 stamp:=clock_timestamp(); -- clock AFTER waiting for locks, never the client's timestamp.
 IF p_action<>'tick' THEN UPDATE challenge_profiles SET last_seen=stamp WHERE user_id=p_user; END IF;
 IF m.status<>'in_progress' THEN RETURN challenge_attack_state(p_match,p_user); END IF;
 IF p_action NOT IN('answer','resume','tick','abandon') THEN RAISE EXCEPTION 'invalid_action'; END IF;
 -- Retry of an accepted Telegram callback never consumes the next question.
 IF p_update IS NOT NULL AND EXISTS(SELECT 1 FROM challenge_match_answers WHERE user_id=p_user AND update_key=p_update) THEN
 RETURN challenge_attack_state(p_match,p_user); END IF;
 IF stamp>=m.server_deadline THEN
 PERFORM challenge_finish_attack(m.id,'expired'); RETURN challenge_attack_state(p_match,p_user); END IF;
 IF p_action='abandon' THEN
 PERFORM challenge_finish_attack(m.id,'abandoned'); RETURN challenge_attack_state(p_match,p_user); END IF;
 IF p_action='answer' AND p_index IS DISTINCT FROM m.question_index THEN
 RETURN challenge_attack_state(p_match,p_user); END IF;
 expired:=stamp>=m.question_deadline;
 IF p_action IN('tick','resume') AND NOT expired THEN RETURN challenge_attack_state(p_match,p_user); END IF;
 q:=m.snapshot->m.question_index;
 IF p_action='answer' AND (p_option IS NULL OR p_option<0 OR p_option>=jsonb_array_length(q->'options')) THEN
 RAISE EXCEPTION 'invalid_option'; END IF;
 correct:=NOT expired AND p_action='answer' AND p_option=(q->>'correct_option_id')::integer;
 ms:=least((m.rules->>'question_seconds')::integer*1000,
 greatest(0,floor(extract(epoch FROM stamp-m.question_opened_at)*1000)::integer));
 pts:=challenge_question_score(correct,ms::numeric/1000,m.rules);
 INSERT INTO challenge_match_answers(match_id,user_id,question_index,question_id,option_id,is_correct,score,elapsed_ms,timed_out,update_key)
 VALUES(m.id,p_user,m.question_index,(q->>'id')::uuid,CASE WHEN expired THEN NULL ELSE p_option END,
 correct,pts,ms,expired,p_update);
 INSERT INTO challenge_events(match_id,event_type,question_index)
 VALUES(m.id,CASE WHEN expired THEN 'question_timed_out' ELSE 'answer_received' END,m.question_index);
 n:=m.question_index+1;
 UPDATE challenge_matches SET question_index=n,question_opened_at=stamp,
 question_deadline=least(m.server_deadline,stamp+make_interval(secs=>(m.rules->>'question_seconds')::integer)) WHERE id=m.id;
 IF n>=jsonb_array_length(m.snapshot) THEN PERFORM challenge_finish_attack(m.id,'completed');
 ELSE INSERT INTO challenge_events(match_id,event_type,question_index) VALUES(m.id,'question_opened',n); END IF;
 RETURN challenge_attack_state(p_match,p_user);
END $$;

-- Keyset navigation in a bounded indexed trophy range. Empty range returns no opponent.
CREATE OR REPLACE FUNCTION public.challenge_find_land(p_user bigint,p_after_trophies integer DEFAULT -1,
 p_after_user bigint DEFAULT 0,p_range integer DEFAULT 500)
RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$
 SELECT to_jsonb(x) FROM (
 SELECT d.user_id,d.display_name,d.trophies FROM challenge_profiles a JOIN challenge_profiles d
 ON d.branch_id=a.branch_id AND d.trophies BETWEEN greatest(0,a.trophies-p_range) AND a.trophies+p_range
 WHERE a.user_id=p_user AND d.user_id<>p_user AND (d.trophies,d.user_id)>(p_after_trophies,p_after_user)
 ORDER BY d.trophies,d.user_id LIMIT 1) x
$$;

-- At-most-once notification claim: no repeated spam if process dies after send.
-- A crash between claim/send may lose a push; permanent attack history is authoritative.
CREATE OR REPLACE FUNCTION public.challenge_claim_notifications(p_limit integer DEFAULT 20)
RETURNS SETOF public.challenge_notifications LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$
DECLARE n challenge_notifications; cfg jsonb; allowed boolean; ids bigint[];
BEGIN
 SELECT array_agg(x.id) INTO ids FROM (SELECT id FROM challenge_notifications WHERE claimed_at IS NULL
 ORDER BY id LIMIT least(greatest(p_limit,1),100) FOR UPDATE SKIP LOCKED) x;
 PERFORM user_id FROM challenge_profiles WHERE user_id IN
 (SELECT user_id FROM challenge_notifications WHERE id=ANY(ids)) ORDER BY user_id FOR UPDATE;
 FOR n IN SELECT * FROM challenge_notifications WHERE id=ANY(ids) ORDER BY id LOOP
 UPDATE challenge_notifications SET claimed_at=clock_timestamp() WHERE id=n.id;
 IF n.kind='attack_completed' THEN
 SELECT rules INTO cfg FROM challenge_matches WHERE id=n.match_id;
 UPDATE challenge_profiles SET last_completion_notification_at=clock_timestamp() WHERE user_id=n.user_id
 AND notifications_enabled AND (last_completion_notification_at IS NULL OR
 last_completion_notification_at<clock_timestamp()-make_interval(secs=>(cfg->>'notification_cooldown_seconds')::integer));
 allowed:=FOUND;
 ELSE SELECT notifications_enabled INTO allowed FROM challenge_profiles WHERE user_id=n.user_id;
 END IF;
 IF allowed THEN RETURN NEXT n; END IF;
 END LOOP;
END $$;

CREATE OR REPLACE VIEW public.challenge_subject_stats WITH (security_invoker=true) AS
SELECT us.user_id,u.subject_id,s.name AS subject_name,
 sum(us.challenges)::bigint AS challenges,sum(us.wins)::bigint AS wins,
 sum(us.correct)::bigint AS correct,sum(us.questions)::bigint AS questions,
 sum(us.response_ms)::bigint AS response_ms,sum(us.responses)::bigint AS responses
FROM public.challenge_unit_stats us JOIN public.challenge_units u ON u.id=us.unit_id
JOIN public.challenge_subjects s ON s.id=u.subject_id
GROUP BY us.user_id,u.subject_id,s.name;
REVOKE ALL ON public.challenge_subject_stats FROM PUBLIC,anon,authenticated;
GRANT SELECT ON public.challenge_subject_stats TO service_role;

-- No direct client access. Trusted bot service_role only; invoker functions never elevate.
DO $$ DECLARE t text; f record; BEGIN
 FOREACH t IN ARRAY ARRAY['challenge_profiles','challenge_towers','challenge_unit_stats','challenge_matches',
 'challenge_match_players','challenge_match_answers','challenge_events','challenge_notifications'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
 EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC, anon, authenticated',t);
 EXECUTE format('GRANT ALL ON public.%I TO service_role',t);
 END LOOP;
 FOR f IN SELECT oid::regprocedure AS sig FROM pg_proc WHERE pronamespace='public'::regnamespace
 AND proname IN('challenge_question_score','challenge_touch_profile','challenge_attack_state','challenge_start_attack',
 'challenge_finish_attack','challenge_advance_attack','challenge_find_land','challenge_claim_notifications') LOOP
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC, anon, authenticated',f.sig);
 EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',f.sig);
 END LOOP;
END $$;
GRANT USAGE, SELECT ON SEQUENCE public.challenge_events_id_seq,public.challenge_notifications_id_seq TO service_role;
